package com.servicerca.model; import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="push_subscription") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class PushSubscription { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @Column(nullable=false,unique=true,columnDefinition="text") private String endpoint; @Column(nullable=false,columnDefinition="text") private String p256dh; @Column(nullable=false,columnDefinition="text") private String auth; @Column(name="created_at",nullable=false) private Instant createdAt; @PrePersist void pre(){if(createdAt==null)createdAt=Instant.now();} }
